// ---------------------------------------------------------------------------------------------
// PL-04 swap enabled with an amm_program outside the compiled allowlist
// ---------------------------------------------------------------------------------------------

#[test]
fn pl_04_amm_program_not_in_allowlist() {
    for flavor in Flavor::DUAL {
        // (a) production build: the mock AMM is not allowlisted
        let Some(mut ctx) = Ctx::builder(flavor)
            .with_swap()
            .no_policy()
            .relay_build(RelayBuild::Default)
            .try_build()
        else {
            return;
        };
        let cfg = ctx.cfg.clone();
        assert_eq!(cfg.amm_program, MOCK_AMM_ID);
        ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)])
            .assert_relay_err(relay_err::INVALID_CONFIG);
        assert!(ctx.svm.get_account(&ctx.policy).is_none());

        // (b) test-amm build: an arbitrary other executable id is still rejected
        let Some(mut ctx) = Ctx::builder(flavor).with_swap().no_policy().try_build() else {
            return;
        };
        let mut cfg = ctx.cfg.clone();
        cfg.amm_program = unique();
        ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)])
            .assert_relay_err(relay_err::INVALID_CONFIG);
        assert!(ctx.svm.get_account(&ctx.policy).is_none());
        // and the real thing initialises under the same build
        let ok = ctx.cfg.clone();
        ctx.send_owner(&[ctx.init_policy_ix(&ok, 0)]).assert_ok();
    }
}

// ---------------------------------------------------------------------------------------------
// PL-05 invalid-config table, each row alone
// ---------------------------------------------------------------------------------------------

#[test]
fn pl_05_invalid_config_table() {
    for flavor in Flavor::DUAL {
        let Some(mut ctx) = Ctx::builder(flavor).with_swap().no_policy().try_build() else {
            return;
        };
        let base = ctx.cfg.clone();
        let mut rows = invalid_config_rows(&base);
        rows.extend(header_alias_rows(
            &base,
            &ctx.mandate,
            &ctx.policy,
            &ctx.authority,
            &ctx.owner.pubkey(),
            &ctx.agent.pubkey(),
        ));
        assert!(rows.len() >= 60, "table has {} rows", rows.len());
        let before = ctx.snapshot();
        let mut failures = Vec::new();
        for row in &rows {
            let r = ctx.send_owner(&[ctx.init_policy_ix(&row.cfg, row.flags)]);
            match &r.result {
                Ok(_) => failures.push(format!("{}: init_policy SUCCEEDED", row.name)),
                Err(_) => {
                    let code = common::assert::custom_code(&r.result);
                    let prog = code.and_then(|c| failing_program(r.logs(), c));
                    if code != Some(relay_err::INVALID_CONFIG) || prog != Some(RELAY_ID) {
                        failures.push(format!(
                            "{}: expected relay 113, got code {:?} from {:?}",
                            row.name,
                            code,
                            prog.map(|p| program_name(&p))
                        ));
                    }
                }
            }
            if ctx.svm.get_account(&ctx.policy).is_some() {
                failures.push(format!("{}: an account was created", row.name));
                // keep going from a clean slate
                ctx.svm.set_account(ctx.policy, Default::default()).ok();
            }
        }
        assert!(
            failures.is_empty(),
            "{} rows misbehaved:\n  {}",
            failures.len(),
            failures.join("\n  ")
        );
        assert_nothing_moved(&before, &ctx.snapshot());
        // the unmutated base is valid
        ctx.send_owner(&[ctx.init_policy_ix(&base, 0)]).assert_ok();
    }
}

use common::assert::program_name;

// ---------------------------------------------------------------------------------------------
// PL-06 init twice
// ---------------------------------------------------------------------------------------------

dual_token!(pl_06_init_policy_twice, |ctx| {
    let first = ctx.policy_bytes();
    let before = ctx.snapshot();
    let mut cfg = ctx.cfg.clone();
    // even with a different (valid) config the second init must fail and change nothing
    cfg.recipients[0] = unique();
    ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)])
        .assert_relay_err(relay_err::INVALID_CONFIG);
    assert_eq!(ctx.policy_bytes(), first, "policy bytes untouched");
    // identical config too
    let same = ctx.cfg.clone();
    ctx.send_owner(&[ctx.init_policy_ix(&same, 0)])
        .assert_relay_err(relay_err::INVALID_CONFIG);
    assert_nothing_moved(&before, &ctx.snapshot());
});

// ---------------------------------------------------------------------------------------------
// PL-07 pre-funded policy PDA
// ---------------------------------------------------------------------------------------------

#[test]
fn pl_07_prefunded_policy_pda() {
    for flavor in Flavor::DUAL {
        // baseline: no pre-funding, measure the fee
        let Some(mut base) = Ctx::builder(flavor).no_policy().try_build() else {
            return;
        };
        let rent = base.svm.rent(944);
        let fee = fee_one_signature(&mut base);
        let b0 = owner_balance(&base);
        let cfg = base.cfg.clone();
        base.send_owner(&[base.init_policy_ix(&cfg, 0)]).assert_ok();
        assert_eq!(
            b0 - owner_balance(&base),
            rent + fee,
            "baseline debit = rent + fee"
        );

        // (a) 1 lamport below rent, (b) exactly rent, (c) more than rent
        for (label, prefund) in [
            ("rent-1", rent - 1),
            ("rent", rent),
            ("rent+777", rent + 777),
        ] {
            let mut ctx = Ctx::builder(flavor).no_policy().try_build().unwrap();
            let policy = ctx.policy;
            ctx.svm.airdrop(&policy, prefund).unwrap(); // a third party funds the address
            let acct = ctx.svm.get_account(&policy).unwrap();
            assert_eq!(acct.owner, SYSTEM_ID, "{label}: system owned before init");
            assert!(acct.data.is_empty());
            let before = owner_balance(&ctx);
            let cfg = ctx.cfg.clone();
            ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)]).assert_ok();
            let acct = ctx.svm.get_account(&policy).unwrap();
            assert_eq!(acct.owner, RELAY_ID, "{label}: owner of policy = relay");
            assert_eq!(acct.data.len(), 944, "{label}");
            assert!(acct.lamports >= rent, "{label}: rent exempt");
            assert_eq!(acct.lamports, prefund.max(rent), "{label}: final lamports");
            let topup = rent.saturating_sub(prefund);
            assert_eq!(
                before - owner_balance(&ctx),
                topup + fee,
                "{label}: owner pays exactly the missing rent (+fee), nothing more"
            );
            assert_eq!(
                acct.data,
                ctx.expected_header(0).encode_with(&cfg),
                "{label}: bytes"
            );
        }
    }
}

// ---------------------------------------------------------------------------------------------
// PL-08 fake mandate
// ---------------------------------------------------------------------------------------------

dual_token!(pl_08_fake_mandate_rows, with | b | b.no_policy(), |ctx| {
    let good = ctx.svm.get_account(&ctx.mandate).unwrap();
    let cfg = ctx.cfg.clone();
    type Edit = Box<dyn Fn(&mut solana_account::Account)>;
    let rows: Vec<(&str, Edit)> = vec![
        ("wrong owner program", Box::new(|a| a.owner = unique())),
        ("owned by the relay", Box::new(|a| a.owner = RELAY_ID)),
        ("length 2135", Box::new(|a| a.data.truncate(2135))),
        ("length 2137", Box::new(|a| a.data.push(0))),
        ("disc != 1", Box::new(|a| a.data[agent_auth::OFF_DISC] = 2)),
        ("disc 0", Box::new(|a| a.data[agent_auth::OFF_DISC] = 0)),
        (
            "active == 0",
            Box::new(|a| a.data[agent_auth::OFF_ACTIVE] = 0),
        ),
    ];
    for (name, edit) in rows {
        let m = ctx.mandate;
        ctx.svm.put(m, good.clone());
        ctx.edit_account(&m, |a| edit(a));
        let r = ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)]);
        if r.is_ok() {
            panic!("{name}: init_policy succeeded");
        }
        r.assert_relay_err(relay_err::INVALID_MANDATE);
        assert!(
            ctx.svm.get_account(&ctx.policy).is_none(),
            "{name}: no account created"
        );
    }
    // a missing mandate account (never created) is also 117
    ctx.svm.put(ctx.mandate, solana_account::Account::default());
    ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)])
        .assert_relay_err(relay_err::INVALID_MANDATE);
});

// ---------------------------------------------------------------------------------------------
// PL-09 mandate whose agent == owner
// ---------------------------------------------------------------------------------------------

dual_token!(
    pl_09_mandate_agent_equals_owner,
    with | b | b.no_policy(),
    |ctx| {
        // the hardened core refuses agent == owner at create_mandate, so seed it
        let owner = ctx.owner.pubkey();
        let m = ctx.mandate;
        ctx.edit_account(&m, |a| {
            a.data[agent_auth::OFF_AGENT..agent_auth::OFF_AGENT + 32]
                .copy_from_slice(owner.as_ref());
        });
        let cfg = ctx.cfg.clone();
        ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)])
            .assert_relay_err(relay_err::INVALID_CONFIG);
        assert!(ctx.svm.get_account(&ctx.policy).is_none());
    }
);

