// ---------------------------------------------------------------------------------------------
// PL-12 init data length 801 and 803
// ---------------------------------------------------------------------------------------------

dual_token!(pl_12_init_data_length, with | b | b.no_policy(), |ctx| {
    let cfg = ctx.cfg.clone();
    let good = ctx.init_policy_ix(&cfg, 0);
    assert_eq!(good.data.len(), 802);
    for len in [0usize, 1, 2, 801, 803, 1000] {
        let mut ix = good.clone();
        ix.data.resize(len, 0);
        if len > 0 {
            ix.data[0] = 0; // tag stays init_policy
        }
        ctx.send_owner(&[ix])
            .assert_relay_err(relay_err::INVALID_INSTRUCTION_DATA);
    }
    assert!(ctx.svm.get_account(&ctx.policy).is_none());
});

// ---------------------------------------------------------------------------------------------
// PL-13 set_paused blocks transfer and swap; unpause restores
// ---------------------------------------------------------------------------------------------

dual_token!(
    pl_13_pause_blocks_transfer_and_swap,
    with | b | b.with_swap(),
    |ctx| {
        ctx.send_owner(&[ctx.set_paused_ix(1)]).assert_ok();
        assert_eq!(ctx.policy_bytes()[off::FLAGS] & FLAG_PAUSED, FLAG_PAUSED);
        let before = ctx.snapshot();
        ctx.send_agent(&[ctx.transfer_ix(1_000)])
            .assert_relay_err(relay_err::PAUSED);
        ctx.send_agent(&[ctx.swap_ix_default(1_000)])
            .assert_relay_err(relay_err::PAUSED);
        assert_nothing_moved(&before, &ctx.snapshot());

        ctx.send_owner(&[ctx.set_paused_ix(0)]).assert_ok();
        assert_eq!(ctx.policy_bytes()[off::FLAGS] & FLAG_PAUSED, 0);
        ctx.send_agent(&[ctx.transfer_ix(1_000)]).assert_ok();
        ctx.send_agent(&[ctx.swap_ix_default(1_000)]).assert_ok();
        assert_eq!(ctx.token_perm().spend_total, 1_000);
    }
);

// ---------------------------------------------------------------------------------------------
// PL-14 set_paused by the agent / owner not signing
// ---------------------------------------------------------------------------------------------

dual_token!(pl_14_set_paused_authorisation, |ctx| {
    let before = ctx.snapshot();
    // the agent signs as "owner": not the policy owner
    let ix = relay_ix::set_paused_ix(&ctx.agent.pubkey(), &ctx.policy, 1);
    ctx.send_agent(&[ix])
        .assert_relay_err(relay_err::NOT_POLICY_OWNER);
    // the attacker too
    let ix = relay_ix::set_paused_ix(&ctx.attacker.pubkey(), &ctx.policy, 1);
    ctx.send_attacker(&[ix])
        .assert_relay_err(relay_err::NOT_POLICY_OWNER);
    // the real owner listed but not signing (the agent pays)
    let ix = ctx.set_paused_ix(1).with_signer(0, false);
    ctx.send_agent(&[ix])
        .assert_relay_err(relay_err::OWNER_NOT_SIGNER);
    assert_nothing_moved(&before, &ctx.snapshot());
    // and the agent can still act: nothing got paused
    ctx.send_agent(&[ctx.transfer_ix(1)]).assert_ok();
});

// ---------------------------------------------------------------------------------------------
// PL-15 close_policy by the owner
// ---------------------------------------------------------------------------------------------

dual_token!(pl_15_close_policy_by_owner, |ctx| {
    let fee = fee_one_signature(ctx);
    let policy_lamports = ctx.svm.get_account(&ctx.policy).unwrap().lamports;
    let before = owner_balance(ctx);
    let r = ctx.send_owner(&[ctx.close_policy_ix()]);
    r.assert_ok();
    assert_eq!(
        owner_balance(ctx),
        before + policy_lamports - fee,
        "exact policy lamports returned to the owner"
    );
    assert!(ctx.svm.get_account(&ctx.policy).is_none(), "account gone");
    assert!(
        r.events().contains(&RelayEvent::PolicyClosed {
            mandate: ctx.mandate,
            policy: ctx.policy
        }),
        "PolicyClosed event"
    );
    // the agent fails closed
    let snap = ctx.snapshot();
    ctx.send_agent(&[ctx.transfer_ix(1_000)])
        .assert_relay_err(relay_err::INVALID_POLICY);
    assert_nothing_moved(&snap, &ctx.snapshot());
    // init_policy again succeeds and the agent works again
    let cfg = ctx.cfg.clone();
    ctx.send_owner(&[ctx.init_policy_ix(&cfg, 0)]).assert_ok();
    ctx.send_agent(&[ctx.transfer_ix(1_000)]).assert_ok();
});

// ---------------------------------------------------------------------------------------------
// PL-16 close_policy signed by someone other than policy.owner
// ---------------------------------------------------------------------------------------------

dual_token!(pl_16_close_policy_by_stranger, |ctx| {
    let before = ctx.snapshot();
    let ix = relay_ix::close_policy_ix(&ctx.attacker.pubkey(), &ctx.policy);
    ctx.send_attacker(&[ix])
        .assert_relay_err(relay_err::NOT_POLICY_OWNER);
    let ix = relay_ix::close_policy_ix(&ctx.agent.pubkey(), &ctx.policy);
    ctx.send_agent(&[ix])
        .assert_relay_err(relay_err::NOT_POLICY_OWNER);
    // owner listed but not signing
    let ix = ctx.close_policy_ix().with_signer(0, false);
    ctx.send_attacker(&[ix])
        .assert_relay_err(relay_err::OWNER_NOT_SIGNER);
    assert_nothing_moved(&before, &ctx.snapshot());
    assert!(ctx.svm.get_account(&ctx.policy).is_some(), "policy intact");
});

// ---------------------------------------------------------------------------------------------
// PL-17 identity header after init
// ---------------------------------------------------------------------------------------------

dual_token!(pl_17_identity_header_after_init, |ctx| {
    let p = ctx.policy_bytes();
    let m = mandate_bytes(ctx);
    assert_eq!(p[off::DISC], 0xA7);
    assert_eq!(p[off::VERSION], 1);
    assert_eq!(
        &p[off::MANDATE_EXPIRY..off::MANDATE_EXPIRY + 8],
        &m[agent_auth::OFF_EXPIRY..agent_auth::OFF_EXPIRY + 8],
        "mandate_expiry == mandate bytes 65..73"
    );
    assert_eq!(&p[off::OWNER..off::OWNER + 32], ctx.owner.pubkey().as_ref());
    assert_eq!(&p[off::AGENT..off::AGENT + 32], ctx.agent.pubkey().as_ref());
    assert_eq!(&p[off::MANDATE..off::MANDATE + 32], ctx.mandate.as_ref());
    let (auth, auth_bump) =
        Pubkey::find_program_address(&[b"authority", ctx.mandate.as_ref()], &RELAY_ID);
    let (pol, pol_bump) =
        Pubkey::find_program_address(&[b"policy", ctx.mandate.as_ref()], &RELAY_ID);
    assert_eq!(pol, ctx.policy);
    assert_eq!(&p[off::AUTHORITY..off::AUTHORITY + 32], auth.as_ref());
    assert_eq!(p[off::POLICY_BUMP], pol_bump);
    assert_eq!(p[off::AUTHORITY_BUMP], auth_bump);
    assert_eq!(&p[5..8], &[0, 0, 0], "reserved0 zero");
    assert_eq!(
        i64::from_le_bytes(
            p[off::MANDATE_EXPIRY..off::MANDATE_EXPIRY + 8]
                .try_into()
                .unwrap()
        ),
        ctx.expiry
    );
});

// ---------------------------------------------------------------------------------------------
